argv:
set -eu
pr=$1; github=$2; expected_head=$3; expected_base=$4; expected_ref=$5; ticket=$6; repo=$7; base=$8; root=$9
emit_internal() {
  kind=$1
  KIND=$kind REPO=$repo GITHUB=$github PR=$pr TICKET=$ticket HEAD=$expected_head HEADREF=$expected_ref BASE=$base MERGE=${landed:-} ROOT=$root bun -e 'const p=process.env; const dbModule=await import(`file://${p.ROOT}/event-runtime/lib/db.mjs`); const chainModule=await import(`file://${p.ROOT}/event-runtime/lib/chain.mjs`); const db=dbModule.openDb(); const rows=db.query(`SELECT run_id FROM runs WHERE state = "RUNNING" AND json_extract(spec_json, "$.agent") = "merge-apply@2" AND json_extract(spec_json, "$.input.plan[0].pr") = ? AND json_extract(spec_json, "$.input.plan[0].headSha") = ?`).all(Number(p.PR),p.HEAD); if(rows.length!==1) throw new Error(`expected one running merge apply, found ${rows.length}`); const causationId=rows[0].run_id; const landed=p.KIND==="landed"; const eventId=landed?`merge-landed:${p.GITHUB}:${p.PR}:${p.MERGE}`:`merge-refresh:${p.REPO}:${p.PR}:${p.HEAD}`; const payload=landed?{repo:p.REPO,github:p.GITHUB,base:p.BASE,pr:Number(p.PR),ticket:p.TICKET,headSha:p.HEAD,headRef:p.HEADREF,mergeCommitSha:p.MERGE}:{repo:p.REPO}; const outcome=chainModule.admitChainEvent(db,await import(`file://${p.ROOT}/event-runtime/lib/registry.mjs`).then(m=>m.loadRegistry()),{schemaVersion:"factory.event/v1",eventId,type:landed?"factory.merge-landed":"factory.merge.requested",subject:p.REPO,occurredAt:new Date().toISOString(),correlationId:eventId,causationId,payload}); db.close(); if(!outcome.admitted&&!outcome.duplicate) throw new Error(outcome.errors.join("; "));'
}
refresh() { emit_internal refresh; }
view=$(gh pr view "$pr" --repo "$github" --json state,isDraft,mergeable,headRefOid,headRefName,baseRefName,labels)
actual_head=$(printf '%s' "$view" | jq -r .headRefOid)
actual_base=$(gh api "repos/$github/git/ref/heads/$base" --jq .object.sha)
if [ "$actual_head" != "$expected_head" ] || [ "$actual_base" != "$expected_base" ]; then refresh; echo "stale reviewed SHA; fresh scan emitted" >&2; exit 0; fi
[ "$(printf '%s' "$view" | jq -r .state)" = OPEN ] || { echo "PR is not open" >&2; exit 1; }
[ "$(printf '%s' "$view" | jq -r .isDraft)" = false ] || { echo "PR is draft" >&2; exit 1; }
[ "$(printf '%s' "$view" | jq -r .mergeable)" = MERGEABLE ] || { refresh; echo "PR is not definitely mergeable" >&2; exit 0; }
[ "$(printf '%s' "$view" | jq -r .headRefName)" = "$expected_ref" ] || { refresh; echo "head branch moved" >&2; exit 0; }
[ "$(printf '%s' "$view" | jq -r .baseRefName)" = "$base" ] || { echo "base branch changed" >&2; exit 1; }
[ "$base" = develop ] || { echo "only develop is auto-mergeable" >&2; exit 1; }
! printf '%s' "$view" | jq -e '[.labels[].name|ascii_downcase] | any(. == "escalated" or . == "ai:escalated")' >/dev/null || { echo "GitHub escalation hold present" >&2; exit 1; }
linear=$(factory linear get "$ticket" --json) || { echo "Linear lookup failed" >&2; exit 1; }
printf '%s' "$linear" | jq -e 'type == "object" and (.state.name | type == "string" and length > 0) and (.labels.nodes | type == "array" and all(.[]; .name | type == "string" and length > 0))' >/dev/null || { echo "Linear lookup was empty or malformed" >&2; exit 1; }
linear_state=$(printf '%s' "$linear" | jq -r .state.name)
linear_labels=$(printf '%s' "$linear" | jq -r '.labels.nodes[].name')
[ "$linear_state" != Blocked ] || { echo "Linear Blocked hold present" >&2; exit 1; }
! printf '%s\n' "$linear_labels" | rg -qi '^(ai:escalated|type:security|.*security.*)$' || { echo "Linear escalation/security hold present" >&2; exit 1; }
checks=$(gh pr checks "$pr" --repo "$github" --required --json bucket)
printf '%s' "$checks" | jq -e 'length > 0 and all(.[]; .bucket == "pass" or .bucket == "skipping")' >/dev/null || { refresh; echo "required CI missing, pending, or red" >&2; exit 0; }
gh pr merge "$pr" --repo "$github" --squash --match-head-commit "$expected_head"
landed=$(gh pr view "$pr" --repo "$github" --json state,mergeCommit --jq 'select(.state == "MERGED") | .mergeCommit.oid')
[ -n "$landed" ] || { echo "merge outcome uncertain" >&2; exit 1; }
emit_internal landed
